[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "packing-list-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "packing-list-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              "title",
              "assumptions_card",
              "packing_tabs"
            ]
          }
        },
        {
          "id": "title",
          "type": "Text",
          "properties": {
            "text": "Everest Base Camp Trek Packing List (October)",
            "style": "titleLarge",
            "horizontalAlignment": "start"
          }
        },
        {
          "id": "assumptions_card",
          "type": "Card",
          "properties": {
            "child": "assumptions_list"
          }
        },
        {
          "id": "assumptions_list",
          "type": "List",
          "properties": {
            "header": "assumptions_header",
            "children": [
              "assumption_1",
              "assumption_2",
              "assumption_3",
              "assumption_4"
            ]
          }
        },
        {
          "id": "assumptions_header",
          "type": "ListHeader",
          "properties": {
            "text": "Assumptions"
          }
        },
        {
          "id": "assumption_1",
          "type": "ListItem",
          "properties": {
            "primaryText": "The trek is 10 days on the trail, not including travel days to/from Kathmandu/Lukla."
          }
        },
        {
          "id": "assumption_2",
          "type": "ListItem",
          "properties": {
            "primaryText": "A porter will carry your main luggage (duffel bag), so a smaller daypack is also needed for daily essentials."
          }
        },
        {
          "id": "assumption_3",
          "type": "ListItem",
          "properties": {
            "primaryText": "You will be staying in teahouses, so a tent and cooking equipment are not required."
          }
        },
        {
          "id": "assumption_4",
          "type": "ListItem",
          "properties": {
            "primaryText": "Temperatures range from 15°C during the day at lower altitudes to -10°C or colder at night and higher altitudes."
          }
        },
        {
          "id": "packing_tabs",
          "type": "Tabs",
          "properties": {
            "children": [
              "clothing_tab",
              "gear_tab",
              "hygiene_tab",
              "first_aid_tab"
            ]
          }
        },
        {
          "id": "clothing_tab",
          "type": "Tab",
          "properties": {
            "label": "Clothing",
            "icon": "/clothing_icon.png",
            "child": "clothing_list"
          }
        },
        {
          "id": "clothing_list",
          "type": "List",
          "properties": {
            "children": [
              "clothing_1",
              "clothing_2",
              "clothing_3",
              "clothing_4",
              "clothing_5",
              "clothing_6",
              "clothing_7",
              "clothing_8",
              "clothing_9",
              "clothing_10"
            ]
          }
        },
        {
          "id": "clothing_1",
          "type": "ListItem",
          "properties": {
            "primaryText": "Base Layers (2-3 sets)",
            "secondaryText": "Lightweight, moisture-wicking thermal tops and bottoms (merino wool or synthetic)."
          }
        },
        {
          "id": "clothing_2",
          "type": "ListItem",
          "properties": {
            "primaryText": "Mid Layers (2-3 items)",
            "secondaryText": "Fleece jacket (200-300 weight).\nLight down jacket or synthetic insulated jacket."
          }
        },
        {
          "id": "clothing_3",
          "type": "ListItem",
          "properties": {
            "primaryText": "Outer Layers (1-2 items)",
            "secondaryText": "Waterproof and windproof shell jacket (Gore-Tex or similar).\nWarm down jacket (600-800 fill power) for evenings and higher altitudes."
          }
        },
        {
          "id": "clothing_4",
          "type": "ListItem",
          "properties": {
            "primaryText": "Trekking Pants (2 pairs)",
            "secondaryText": "Durable, quick-drying trekking trousers (convertible options are good).\nFleece-lined or warm trekking pants for colder days."
          }
        },
        {
          "id": "clothing_5",
          "type": "ListItem",
          "properties": {
            "primaryText": "Warm Trousers/Fleece Pants (1 pair)",
            "secondaryText": "For evenings at teahouses."
          }
        },
        {
          "id": "clothing_6",
          "type": "ListItem",
          "properties": {
            "primaryText": "Underwear (5-7 pairs)",
            "secondaryText": "Moisture-wicking, comfortable."
          }
        },
        {
          "id": "clothing_7",
          "type": "ListItem",
          "properties": {
            "primaryText": "Socks (5-6 pairs)",
            "secondaryText": "Wool or synthetic trekking socks (various thicknesses).\nLiner socks (optional, helps prevent blisters)."
          }
        },
        {
          "id": "clothing_8",
          "type": "ListItem",
          "properties": {
            "primaryText": "Gloves (2 pairs)",
            "secondaryText": "Thin liner gloves.\nWarm, waterproof outer gloves or mittens."
          }
        },
        {
          "id": "clothing_9",
          "type": "ListItem",
          "properties": {
            "primaryText": "Headwear (2-3 items)",
            "secondaryText": "Warm wool or fleece beanie/hat.\nSun hat or cap.\nNeck gaiter or buff."
          }
        },
        {
          "id": "clothing_10",
          "type": "ListItem",
          "properties": {
            "primaryText": "Sleepwear",
            "secondaryText": "Can use a clean set of base layers."
          }
        },
        {
          "id": "gear_tab",
          "type": "Tab",
          "properties": {
            "label": "Gear",
            "icon": "/gear_icon.png",
            "child": "gear_list"
          }
        },
        {
          "id": "gear_list",
          "type": "List",
          "properties": {
            "children": [
              "gear_1",
              "gear_2",
              "gear_3",
              "gear_4",
              "gear_5",
              "gear_6",
              "gear_7",
              "gear_8",
              "gear_9"
            ]
          }
        },
        {
          "id": "gear_1",
          "type": "ListItem",
          "properties": {
            "primaryText": "Backpacks",
            "secondaryText": "Large duffel bag (80-100L) for porter.\nDaypack (25-35L) for personal daily essentials."
          }
        },
        {
          "id": "gear_2",
          "type": "ListItem",
          "properties": {
            "primaryText": "Sleeping Bag",
            "secondaryText": "Rated to at least -10°C (comfort rating), possibly -15°C to -20°C for colder sleepers."
          }
        },
        {
          "id": "gear_3",
          "type": "ListItem",
          "properties": {
            "primaryText": "Footwear",
            "secondaryText": "Sturdy, waterproof, broken-in trekking boots.\nCamp shoes, sandals, or crocs for evenings."
          }
        },
        {
          "id": "gear_4",
          "type": "ListItem",
          "properties": {
            "primaryText": "Trekking Poles",
            "secondaryText": "Highly recommended for stability and reducing knee strain."
          }
        },
        {
          "id": "gear_5",
          "type": "ListItem",
          "properties": {
            "primaryText": "Water Storage",
            "secondaryText": "2 x 1L Nalgene bottles.\nHydration reservoir (2-3L, ensure tube doesn't freeze)."
          }
        },
        {
          "id": "gear_6",
          "type": "ListItem",
          "properties": {
            "primaryText": "Headlamp",
            "secondaryText": "With fresh batteries and spare set."
          }
        },
        {
          "id": "gear_7",
          "type": "ListItem",
          "properties": {
            "primaryText": "Eyewear",
            "secondaryText": "High-quality sunglasses with UV protection (Category 3 or 4)."
          }
        },
        {
          "id": "gear_8",
          "type": "ListItem",
          "properties": {
            "primaryText": "Electronics",
            "secondaryText": "Power bank, camera, phone, chargers, and universal travel adapter."
          }
        },
        {
          "id": "gear_9",
          "type": "ListItem",
          "properties": {
            "primaryText": "Miscellaneous",
            "secondaryText": "Quick-dry towel, padlock, dry bags, book, map, thermos, snacks, reusable bag."
          }
        },
        {
          "id": "hygiene_tab",
          "type": "Tab",
          "properties": {
            "label": "Hygiene & Personal",
            "icon": "/hygiene_icon.png",
            "child": "hygiene_list"
          }
        },
        {
          "id": "hygiene_list",
          "type": "List",
          "properties": {
            "children": [
              "hygiene_1",
              "hygiene_2",
              "hygiene_3",
              "hygiene_4",
              "hygiene_5",
              "hygiene_6",
              "hygiene_7",
              "hygiene_8"
            ]
          }
        },
        {
          "id": "hygiene_1",
          "type": "ListItem",
          "properties": {
            "primaryText": "Toiletries",
            "secondaryText": "Toothbrush, toothpaste, biodegradable soap/shampoo, deodorant."
          }
        },
        {
          "id": "hygiene_2",
          "type": "ListItem",
          "properties": {
            "primaryText": "Hand Sanitizer",
            "secondaryText": "Essential for hygiene on the trail."
          }
        },
        {
          "id": "hygiene_3",
          "type": "ListItem",
          "properties": {
            "primaryText": "Wet Wipes",
            "secondaryText": "For sponge baths or cleaning."
          }
        },
        {
          "id": "hygiene_4",
          "type": "ListItem",
          "properties": {
            "primaryText": "Sun Protection",
            "secondaryText": "High SPF sunscreen (SPF 30-50+) and lip balm with SPF."
          }
        },
        {
          "id": "hygiene_5",
          "type": "ListItem",
          "properties": {
            "primaryText": "Toilet Paper",
            "secondaryText": "Small roll, as not always available in teahouse toilets."
          }
        },
        {
          "id": "hygiene_6",
          "type": "ListItem",
          "properties": {
            "primaryText": "Moisturizer",
            "secondaryText": "For face and hands, to combat dry air."
          }
        },
        {
          "id": "hygiene_7",
          "type": "ListItem",
          "properties": {
            "primaryText": "Personal Medications",
            "secondaryText": "Any prescription medications you require (with a copy of the prescription)."
          }
        },
        {
          "id": "hygiene_8",
          "type": "ListItem",
          "properties": {
            "primaryText": "Feminine Hygiene Products",
            "secondaryText": "As needed."
          }
        },
        {
          "id": "first_aid_tab",
          "type": "Tab",
          "properties": {
            "label": "First-Aid & Health",
            "icon": "/first_aid_icon.png",
            "child": "first_aid_list"
          }
        },
        {
          "id": "first_aid_list",
          "type": "List",
          "properties": {
            "children": [
              "first_aid_1"
            ]
          }
        },
        {
          "id": "first_aid_1",
          "type": "ListItem",
          "properties": {
            "primaryText": "Basic Pain Relief",
            "secondaryText": "Ibuprofen"
          }
        }
      ]
    }
  }
]
